package org.brianwebb.hamsprint.data

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.brianwebb.hamsprint.domain.LicenseClass
import org.brianwebb.hamsprint.domain.Question
import org.brianwebb.hamsprint.domain.QuestionGroup
import org.brianwebb.hamsprint.domain.QuestionPool
import org.brianwebb.hamsprint.domain.Subelement
import java.io.InputStream
import java.time.LocalDate
import java.util.concurrent.ConcurrentHashMap

/**
 * Reads the bundled NCVEC pools (generated by tools/pool/build_pools.py).
 * Pools are immutable, so each is parsed once and cached.
 */
class PoolLoader(private val open: (path: String) -> InputStream) {
    private val cache = ConcurrentHashMap<LicenseClass, QuestionPool>()
    private val json = Json { ignoreUnknownKeys = true }

    fun load(license: LicenseClass): QuestionPool = cache.getOrPut(license) {
        val text = open("pools/${license.poolId}.json").use { it.readBytes().decodeToString() }
        json.decodeFromString<PoolJson>(text).toDomain(license)
    }

    @Serializable
    private data class PoolJson(
        val id: String,
        val poolName: String,
        val validFrom: String,
        val validThrough: String,
        val revision: String,
        val examQuestions: Int,
        val passingScore: Int,
        val subelements: List<SubelementJson>,
        val questions: List<QuestionJson>,
    ) {
        fun toDomain(license: LicenseClass): QuestionPool {
            require(id == license.poolId) { "Pool file $id does not match ${license.poolId}" }
            val byGroup = questions.groupBy { it.group }
            return QuestionPool(
                license = license,
                name = poolName,
                validFrom = LocalDate.parse(validFrom),
                validThrough = LocalDate.parse(validThrough),
                revision = revision,
                examQuestions = examQuestions,
                passingScore = passingScore,
                subelements = subelements.map { s ->
                    Subelement(
                        id = s.id,
                        title = s.title,
                        groups = s.groups.map { g ->
                            QuestionGroup(g.id, g.title, byGroup[g.id].orEmpty().map { it.toDomain() })
                        },
                    )
                },
            )
        }
    }

    @Serializable
    private data class SubelementJson(val id: String, val title: String, val groups: List<GroupJson>)

    @Serializable
    private data class GroupJson(val id: String, val title: String)

    @Serializable
    private data class QuestionJson(
        val id: String,
        val group: String,
        val question: String,
        val answers: List<String>,
        val correct: Int,
        val refs: String? = null,
        val figure: String? = null,
    ) {
        fun toDomain() = Question(id, group, question, answers, correct, refs, figure)
    }
}
